// Ver arquivo email_code_1_limpar.js do manual
const items = $input.all();
const output = [];

for (const item of items) {
  try {
    let texto = item.json.text || item.json.snippet || '';
    texto = texto.replace(/<[^>]*>/g, ' ');
    texto = texto.split(/\n\s*(On .* wrote:|Em .* escreveu:|-----\s*Original Message\s*-----)/i)[0];
    texto = texto.split('\n').filter((linha) => !linha.trim().startsWith('>')).join('\n');
    texto = texto.replace(/\s{2,}/g, ' ').trim();
    const LIMITE = 3000;
    if (texto.length > LIMITE) texto = texto.slice(0, LIMITE) + '...';

    output.push({ json: {
      emailId: item.json.id,
      threadId: item.json.threadId,
      remetente: item.json.from?.value?.[0]?.address || item.json.from || 'desconhecido',
      assunto: item.json.subject || '(sem assunto)',
      textoLimpo: texto || '(e-mail sem conteúdo de texto legível)'
    }});
  } catch (err) {
    output.push({ json: { erro: true, motivo: `Falha ao limpar e-mail: ${err.message}`, emailId: item.json?.id || 'desconhecido' } });
  }
}

return output;

// Ver arquivo email_code_2_validar_ia.js do manual
const CATEGORIAS_VALIDAS = ['Suporte', 'Vendas', 'Financeiro', 'Outro'];
const items = $input.all();
const output = [];

for (const item of items) {
  const dados = $('Limpar e Preparar Texto').item.json;
  try {
    let bruto = item.json.message?.content || item.json.choices?.[0]?.message?.content || item.json.text || '';
    bruto = bruto.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(bruto);
    const categoria = CATEGORIAS_VALIDAS.includes(parsed.categoria) ? parsed.categoria : 'Outro';
    const confianca = (typeof parsed.confianca === 'number' && parsed.confianca >= 0 && parsed.confianca <= 1) ? parsed.confianca : 0;

    output.push({ json: {
      erro: false, emailId: dados.emailId, threadId: dados.threadId, remetente: dados.remetente, assunto: dados.assunto,
      categoria, confianca, respostaSugerida: parsed.resposta_sugerida || '', confiancaAlta: confianca >= 0.8
    }});
  } catch (err) {
    output.push({ json: {
      erro: true, motivo: `Falha ao interpretar resposta da IA: ${err.message}`,
      emailId: dados.emailId, threadId: dados.threadId, remetente: dados.remetente, assunto: dados.assunto,
      categoria: 'Outro', confianca: 0, respostaSugerida: '', confiancaAlta: false
    }});
  }
}

return output;

